<p class="eyebrow">Your selection</p><h1>Shopping cart</h1>
<?php if (!$cart['items']): ?><div class="empty-state panel"><h2>Your cart is empty</h2><p class="muted">Choose something from the store to get started.</p><a class="btn" href="<?= e_attr($basePath) ?>/store">Browse products</a></div><?php else: ?><form method="post" class="cart-layout"><?= $csrf->field() ?><section class="panel"><?php foreach ($cart['items'] as $line): $p=$line['product']; ?><div class="cart-line"><div><strong><?= e($p['name']) ?></strong><br><small class="muted"><?= e($p['sku']) ?> · $<?= number_format((int)$p['price_minor']/100,2) ?> each</small></div><label><span class="sr-only">Quantity</span><input type="number" name="quantity[<?= (int)$p['id'] ?>]" value="<?= (int)$line['quantity'] ?>" min="0" max="99" aria-label="Quantity for <?= e_attr($p['name']) ?>"></label><strong class="line-total">$<?= number_format((int)$line['line_total_minor']/100,2) ?></strong></div><?php endforeach; ?><div class="product-actions"><button class="btn secondary">Update cart</button><a href="<?= e_attr($basePath) ?>/store">Continue shopping</a></div></section><aside class="panel summary"><h2>Order summary</h2><div class="summary-row summary-total"><strong>Total</strong><strong><?= e($cart['currency']) ?> $<?= number_format((int)$cart['subtotal']/100,2) ?></strong></div><p class="muted">Taxes or delivery charges, when applicable, will be confirmed by the business.</p><a class="btn" href="<?= e_attr($basePath) ?>/checkout">Continue to checkout</a></aside></form><?php endif; ?>
